"""Fake OpenAI and Anthropic provider. The scenario is the request's model name."""

from trueup.fake.server import SCENARIOS, FakeProvider, TruthLog

__all__ = ["SCENARIOS", "FakeProvider", "TruthLog"]
"""Anthropic Messages: POST /v1/messages."""

from __future__ import annotations

import json
from typing import Any

from trueup.fake.reply import Ids, Reply, json_reply, sse, stream_reply

SCENARIOS = (
    "anth-plain",
    "anth-thinking",
    "anth-tools",
    "anth-error-event",
    "anth-cut",
    "anth-529",
)
INPUT_TOKENS = 5
OUTPUT_TOKENS = 3
THINKING = "Need the weather."
TOOL_INPUT = {"city": "Lagos"}


def _content(scenario: str, ids: Ids) -> list[dict[str, Any]]:
    blocks: list[dict[str, Any]] = []
    if scenario in ("anth-thinking", "anth-tools"):
        blocks.append({"type": "thinking", "thinking": THINKING, "signature": "fake-sig"})
    blocks.append({"type": "text", "text": "hello"})
    if scenario == "anth-tools":
        blocks.append({"type": "tool_use", "id": ids.new("toolu_"), "name": "get_weather", "input": TOOL_INPUT})
    return blocks


def _facts(mid: str, content: list[dict[str, Any]], stop: str) -> dict[str, Any]:
    return {
        "response_id": mid,
        "usage": {"input_tokens": INPUT_TOKENS, "output_tokens": OUTPUT_TOKENS, "total_tokens": INPUT_TOKENS + OUTPUT_TOKENS},
        "finish": [stop],
        "tool_calls": [
            {"id": b["id"], "name": b["name"], "arguments": json.dumps(b["input"], separators=(",", ":"))}
            for b in content
            if b["type"] == "tool_use"
        ],
        "text": ["".join(b["text"] for b in content if b["type"] == "text")],
    }


def handle(scenario: str, req: dict[str, Any], ids: Ids) -> Reply:
    if scenario == "anth-529":
        return json_reply(
            529,
            {"type": "error", "error": {"type": "overloaded_error", "message": "Overloaded"}},
            outcome="http_error",
        )
    mid = ids.new("msg_")
    model = req.get("model", "")
    content = _content(scenario, ids)
    stop = "tool_use" if scenario == "anth-tools" else "end_turn"
    if not req.get("stream"):
        body = {
            "id": mid,
            "type": "message",
            "role": "assistant",
            "model": model,
            "content": content,
            "stop_reason": stop,
            "stop_sequence": None,
            "usage": {"input_tokens": INPUT_TOKENS, "output_tokens": OUTPUT_TOKENS},
        }
        if scenario == "anth-cut":
            raw = json.dumps(body).encode()
            return Reply(200, raw[: len(raw) // 2], cut=True, response_id=mid, outcome="cut")
        if scenario == "anth-error-event":
            return json_reply(400, {"type": "error", "error": {"type": "invalid_request_error", "message": "anth-error-event needs stream=true"}}, outcome="http_error")
        return json_reply(200, body, **_facts(mid, content, stop))

    def ev(kind: str, **data: Any) -> bytes:
        return sse({"type": kind, **data}, event=kind)

    parts = [
        ev("message_start", message={
            "id": mid, "type": "message", "role": "assistant", "model": model, "content": [],
            "stop_reason": None, "stop_sequence": None,
            "usage": {"input_tokens": INPUT_TOKENS, "output_tokens": 1},
        })
    ]
    for i, block in enumerate(content):
        if block["type"] == "thinking":
            parts += [
                ev("content_block_start", index=i, content_block={"type": "thinking", "thinking": "", "signature": ""}),
                ev("content_block_delta", index=i, delta={"type": "thinking_delta", "thinking": block["thinking"]}),
                ev("content_block_delta", index=i, delta={"type": "signature_delta", "signature": block["signature"]}),
            ]
        elif block["type"] == "text":
            parts += [
                ev("content_block_start", index=i, content_block={"type": "text", "text": ""}),
                ev("content_block_delta", index=i, delta={"type": "text_delta", "text": "hel"}),
            ]
            if scenario == "anth-error-event":
                parts.append(ev("error", error={"type": "overloaded_error", "message": "Overloaded"}))
                return stream_reply(parts, response_id=mid, outcome="error_event", text=["hel"])
            if scenario == "anth-cut":
                return stream_reply(parts, cut=True, response_id=mid, outcome="cut", text=["hel"])
            parts.append(ev("content_block_delta", index=i, delta={"type": "text_delta", "text": "lo"}))
        else:
            parts += [
                ev("content_block_start", index=i, content_block={"type": "tool_use", "id": block["id"], "name": block["name"], "input": {}}),
                ev("content_block_delta", index=i, delta={"type": "input_json_delta", "partial_json": '{"city": '}),
                ev("content_block_delta", index=i, delta={"type": "input_json_delta", "partial_json": '"Lagos"}'}),
            ]
        parts.append(ev("content_block_stop", index=i))
    parts += [
        ev("message_delta", delta={"stop_reason": stop, "stop_sequence": None}, usage={"output_tokens": OUTPUT_TOKENS}),
        ev("message_stop"),
    ]
    return stream_reply(parts, **_facts(mid, content, stop))
"""OpenAI Chat Completions: POST /v1/chat/completions."""

from __future__ import annotations

from typing import Any

from trueup.fake.reply import Ids, Reply, json_reply, sse, stream_reply

USAGE = {"prompt_tokens": 11, "completion_tokens": 7, "total_tokens": 18}
SCENARIOS = (
    "chat-plain",
    "chat-tools",
    "chat-refusal",
    "chat-n2",
    "chat-500",
    "chat-error-event",
    "chat-cut",
)
REFUSAL = "I can't help with that."


def _usage_facts() -> dict[str, int]:
    return {
        "input_tokens": USAGE["prompt_tokens"],
        "output_tokens": USAGE["completion_tokens"],
        "total_tokens": USAGE["total_tokens"],
    }


def _tool_calls(ids: Ids) -> list[dict[str, Any]]:
    return [
        {
            "id": ids.new("call_"),
            "type": "function",
            "function": {"name": "get_weather", "arguments": '{"city":"Lagos"}'},
        },
        {
            "id": ids.new("call_"),
            "type": "function",
            "function": {"name": "get_time", "arguments": '{"tz":"WAT"}'},
        },
    ]


def _choices(scenario: str, ids: Ids) -> list[dict[str, Any]]:
    """The message(s) a scenario answers with, as non-streamed choices."""
    if scenario == "chat-tools":
        msg = {"role": "assistant", "content": None, "tool_calls": _tool_calls(ids)}
        return [{"index": 0, "message": msg, "finish_reason": "tool_calls"}]
    if scenario == "chat-refusal":
        msg = {"role": "assistant", "content": None, "refusal": REFUSAL}
        return [{"index": 0, "message": msg, "finish_reason": "stop"}]
    if scenario == "chat-n2":
        return [
            {"index": i, "message": {"role": "assistant", "content": t}, "finish_reason": "stop"}
            for i, t in enumerate(("one", "two"))
        ]
    return [{"index": 0, "message": {"role": "assistant", "content": "hello"}, "finish_reason": "stop"}]


def _facts(choices: list[dict[str, Any]]) -> dict[str, Any]:
    tools = []
    for c in choices:
        for t in c["message"].get("tool_calls") or []:
            tools.append({"id": t["id"], "name": t["function"]["name"], "arguments": t["function"]["arguments"]})
    return {
        "finish": [c["finish_reason"] for c in choices],
        "tool_calls": tools,
        "text": [c["message"].get("content") or c["message"].get("refusal") or "" for c in choices],
    }


def handle(scenario: str, req: dict[str, Any], ids: Ids) -> Reply:
    if scenario == "chat-500":
        return json_reply(
            500,
            {"error": {"message": "fake server error", "type": "server_error", "code": None, "param": None}},
            outcome="http_error",
        )
    rid = ids.new("chatcmpl-")
    model = req.get("model", "")
    if not req.get("stream"):
        choices = _choices(scenario, ids)
        body = {
            "id": rid,
            "object": "chat.completion",
            "created": 0,
            "model": model,
            "choices": choices,
            "usage": USAGE,
        }
        if scenario == "chat-cut":
            raw = json_reply(200, body).body
            return Reply(200, raw[: len(raw) // 2], cut=True, response_id=rid, outcome="cut")
        if scenario == "chat-error-event":
            return json_reply(400, {"error": {"message": "chat-error-event needs stream=true", "type": "invalid_request_error"}}, outcome="http_error")
        return json_reply(200, body, response_id=rid, usage=_usage_facts(), **_facts(choices))
    return _stream(scenario, req, ids, rid, model)


def _stream(scenario: str, req: dict[str, Any], ids: Ids, rid: str, model: str) -> Reply:
    def chunk(choices: list[dict[str, Any]], usage: dict[str, int] | None = None) -> bytes:
        d: dict[str, Any] = {"id": rid, "object": "chat.completion.chunk", "created": 0, "model": model, "choices": choices}
        if usage is not None:
            d["usage"] = usage
        return sse(d)

    def delta(d: dict[str, Any], index: int = 0, finish: str | None = None) -> bytes:
        return chunk([{"index": index, "delta": d, "finish_reason": finish}])

    choices = _choices(scenario, ids)
    parts = [delta({"role": "assistant", "content": ""}, i) for i in range(len(choices))]
    if scenario == "chat-tools":
        # Two parallel calls, arguments split across chunks and interleaved.
        a, b = choices[0]["message"]["tool_calls"]
        parts += [
            delta({"tool_calls": [{"index": 0, "id": a["id"], "type": "function", "function": {"name": "get_weather", "arguments": ""}}]}),
            delta({"tool_calls": [{"index": 1, "id": b["id"], "type": "function", "function": {"name": "get_time", "arguments": ""}}]}),
            delta({"tool_calls": [{"index": 0, "function": {"arguments": '{"city":'}}]}),
            delta({"tool_calls": [{"index": 1, "function": {"arguments": '{"tz":"WAT"}'}}]}),
            delta({"tool_calls": [{"index": 0, "function": {"arguments": '"Lagos"}'}}]}),
            delta({}, 0, "tool_calls"),
        ]
    elif scenario == "chat-refusal":
        parts += [delta({"refusal": "I can't "}), delta({"refusal": "help with that."}), delta({}, 0, "stop")]
    elif scenario == "chat-n2":
        parts += [delta({"content": "one"}, 0), delta({"content": "two"}, 1), delta({}, 0, "stop"), delta({}, 1, "stop")]
    else:
        parts.append(delta({"content": "hel"}))
        if scenario == "chat-error-event":
            parts.append(sse({"error": {"message": "fake stream error", "type": "server_error"}}))
            return stream_reply(parts, response_id=rid, outcome="error_event", text=["hel"])
        if scenario == "chat-cut":
            r = stream_reply(parts, response_id=rid, outcome="cut", text=["hel"])
            r.cut = True
            return r
        parts += [delta({"content": "lo"}), delta({}, 0, "stop")]
    include_usage = bool((req.get("stream_options") or {}).get("include_usage"))
    if include_usage:
        parts.append(chunk([], usage=USAGE))
    parts.append(b"data: [DONE]\n\n")
    return stream_reply(parts, response_id=rid, usage=_usage_facts() if include_usage else None, **_facts(choices))
"""OpenAI Responses: POST /v1/responses."""

from __future__ import annotations

import copy
import json
from typing import Any

from trueup.fake.reply import Ids, Reply, json_reply, sse, stream_reply

SCENARIOS = (
    "resp-plain",
    "resp-tool",
    "resp-reasoning",
    "resp-failed",
    "resp-incomplete",
    "resp-error-event",
    "resp-cut",
)
INPUT_TOKENS = 11
OUTPUT_TOKENS = 7
REASONING_TOKENS = 4
SUMMARY = "Think about the weather."


def _usage(reasoning: int = 0) -> dict[str, Any]:
    return {
        "input_tokens": INPUT_TOKENS,
        "output_tokens": OUTPUT_TOKENS,
        "total_tokens": INPUT_TOKENS + OUTPUT_TOKENS,
        "input_tokens_details": {"cached_tokens": 0},
        "output_tokens_details": {"reasoning_tokens": reasoning},
    }


def _message(ids: Ids, text: str, status: str = "completed") -> dict[str, Any]:
    return {
        "type": "message",
        "id": ids.new("msg_"),
        "role": "assistant",
        "status": status,
        "content": [{"type": "output_text", "text": text, "annotations": []}],
    }


def _body(scenario: str, model: str, ids: Ids) -> dict[str, Any]:
    reasoning = 0
    status = "completed"
    error = None
    incomplete = None
    if scenario == "resp-tool":
        output = [
            {
                "type": "function_call",
                "id": ids.new("fc_"),
                "call_id": ids.new("call_"),
                "name": "get_weather",
                "arguments": '{"city":"Lagos"}',
                "status": "completed",
            }
        ]
    elif scenario == "resp-reasoning":
        reasoning = REASONING_TOKENS
        output = [
            {"type": "reasoning", "id": ids.new("rs_"), "summary": [{"type": "summary_text", "text": SUMMARY}]},
            _message(ids, "hello"),
        ]
    elif scenario == "resp-failed":
        status = "failed"
        error = {"code": "server_error", "message": "fake response failed"}
        output = []
    elif scenario == "resp-incomplete":
        status = "incomplete"
        incomplete = {"reason": "max_output_tokens"}
        output = [_message(ids, "The answer is cut", status="incomplete")]
    else:
        output = [_message(ids, "hello")]
    return {
        "id": ids.new("resp_"),
        "object": "response",
        "created_at": 0,
        "status": status,
        "error": error,
        "incomplete_details": incomplete,
        "model": model,
        "output": output,
        "parallel_tool_calls": True,
        "tool_choice": "auto",
        "tools": [],
        "usage": None if status == "failed" else _usage(reasoning),
    }


def _facts(body: dict[str, Any]) -> dict[str, Any]:
    usage = body["usage"]
    texts, tools = [], []
    for item in body["output"]:
        if item["type"] == "message":
            texts.append("".join(c["text"] for c in item["content"]))
        elif item["type"] == "function_call":
            tools.append({"id": item["call_id"], "name": item["name"], "arguments": item["arguments"]})
    return {
        "response_id": body["id"],
        "outcome": body["status"] if body["status"] != "completed" else "complete",
        "usage": None
        if usage is None
        else {
            "input_tokens": usage["input_tokens"],
            "output_tokens": usage["output_tokens"],
            "total_tokens": usage["total_tokens"],
            "reasoning_tokens": usage["output_tokens_details"]["reasoning_tokens"],
        },
        "finish": [body["status"]],
        "tool_calls": tools,
        "text": texts,
    }


def handle(scenario: str, req: dict[str, Any], ids: Ids) -> Reply:
    body = _body(scenario, req.get("model", ""), ids)
    if not req.get("stream"):
        if scenario == "resp-cut":
            raw = json.dumps(body).encode()
            return Reply(200, raw[: len(raw) // 2], cut=True, response_id=body["id"], outcome="cut")
        if scenario == "resp-error-event":
            return json_reply(400, {"error": {"message": "resp-error-event needs stream=true", "type": "invalid_request_error"}}, outcome="http_error")
        return json_reply(200, body, **_facts(body))
    return _stream(scenario, body)


def _stream(scenario: str, body: dict[str, Any]) -> Reply:
    seq = 0
    parts: list[bytes] = []

    def ev(kind: str, **data: Any) -> None:
        nonlocal seq
        data = {"type": kind, "sequence_number": seq, **data}
        seq += 1
        parts.append(sse(data, event=kind))

    start = dict(body, status="in_progress", output=[], usage=None, error=None, incomplete_details=None)
    ev("response.created", response=start)
    ev("response.in_progress", response=start)
    for i, item in enumerate(body["output"]):
        added = copy.deepcopy(item)
        added["status"] = "in_progress"
        if item["type"] == "message":
            added["content"] = []
        elif item["type"] == "function_call":
            added["arguments"] = ""
        elif item["type"] == "reasoning":
            added["summary"] = []
        ev("response.output_item.added", output_index=i, item=added)
        if item["type"] == "message":
            text = item["content"][0]["text"]
            first, rest = text[:3], text[3:]
            ev("response.content_part.added", item_id=item["id"], output_index=i, content_index=0,
               part={"type": "output_text", "text": "", "annotations": []})
            ev("response.output_text.delta", item_id=item["id"], output_index=i, content_index=0, delta=first, logprobs=[])
            if scenario == "resp-error-event":
                ev("error", code="server_error", message="fake stream error", param=None)
                return stream_reply(parts, response_id=body["id"], outcome="error_event", text=[first])
            if scenario == "resp-cut":
                return stream_reply(parts, cut=True, response_id=body["id"], outcome="cut", text=[first])
            ev("response.output_text.delta", item_id=item["id"], output_index=i, content_index=0, delta=rest, logprobs=[])
            ev("response.output_text.done", item_id=item["id"], output_index=i, content_index=0, text=text, logprobs=[])
            ev("response.content_part.done", item_id=item["id"], output_index=i, content_index=0, part=item["content"][0])
        elif item["type"] == "function_call":
            args = item["arguments"]
            half = len(args) // 2
            ev("response.function_call_arguments.delta", item_id=item["id"], output_index=i, delta=args[:half])
            ev("response.function_call_arguments.delta", item_id=item["id"], output_index=i, delta=args[half:])
            ev("response.function_call_arguments.done", item_id=item["id"], output_index=i, arguments=args, name=item["name"])
        elif item["type"] == "reasoning":
            s = item["summary"][0]
            ev("response.reasoning_summary_part.added", item_id=item["id"], output_index=i, summary_index=0,
               part={"type": "summary_text", "text": ""})
            ev("response.reasoning_summary_text.delta", item_id=item["id"], output_index=i, summary_index=0, delta=s["text"])
            ev("response.reasoning_summary_text.done", item_id=item["id"], output_index=i, summary_index=0, text=s["text"])
            ev("response.reasoning_summary_part.done", item_id=item["id"], output_index=i, summary_index=0, part=s)
        ev("response.output_item.done", output_index=i, item=item)
    final = {"completed": "response.completed", "failed": "response.failed", "incomplete": "response.incomplete"}
    ev(final[body["status"]], response=body)
    return stream_reply(parts, **_facts(body))
"""What the fake sends back for one request, plus the facts the truth log keeps."""

from __future__ import annotations

import itertools
import json
import secrets
import threading
from dataclasses import dataclass, field
from typing import Any


@dataclass
class Reply:
    status: int
    body: bytes
    content_type: str = "application/json"
    # Write the body, then drop the connection before the declared length.
    cut: bool = False
    # Truth facts about this reply.
    response_id: str | None = None
    outcome: str = "complete"  # complete, failed, incomplete, error_event, cut, http_error
    usage: dict[str, int] | None = None  # None means the fake sent no usage
    finish: list[str | None] = field(default_factory=list)
    tool_calls: list[dict[str, Any]] = field(default_factory=list)
    text: list[str] = field(default_factory=list)
    headers: dict[str, str] = field(default_factory=dict)

    def facts(self) -> dict[str, Any]:
        return {
            "status_code": self.status,
            "response_id": self.response_id,
            "outcome": self.outcome,
            "usage": dict(self.usage) if self.usage is not None else None,
            "usage_sent": self.usage is not None,
            "finish": list(self.finish),
            "tool_calls": [dict(t) for t in self.tool_calls],
            "text": list(self.text),
        }


class Ids:
    """Ids unique per call and per server instance.

    Reusing a response id across calls makes some libraries treat the second
    span as a duplicate and drop it, so every id carries a per-server token and
    a counter.
    """

    def __init__(self) -> None:
        self._token = secrets.token_hex(4)
        self._count = itertools.count(1)
        self._lock = threading.Lock()

    def new(self, prefix: str) -> str:
        with self._lock:
            n = next(self._count)
        return f"{prefix}{self._token}{n:04d}"


def dumps(obj: Any) -> bytes:
    return json.dumps(obj, separators=(",", ":")).encode()


def json_reply(status: int, obj: Any, **kw: Any) -> Reply:
    return Reply(status=status, body=dumps(obj), **kw)


def sse(data: Any, event: str | None = None) -> bytes:
    head = f"event: {event}\n" if event else ""
    payload = data if isinstance(data, str) else json.dumps(data, separators=(",", ":"))
    return f"{head}data: {payload}\n\n".encode()


def stream_reply(parts: list[bytes], **kw: Any) -> Reply:
    return Reply(status=200, body=b"".join(parts), content_type="text/event-stream", **kw)
"""Local HTTP fake provider. Runs in a thread on a random free port."""

from __future__ import annotations

import json
import socket
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any, Callable

from trueup.fake import anthropic_messages, openai_chat, openai_responses
from trueup.fake.reply import Ids, Reply, json_reply

ROUTES: dict[str, tuple[str, Callable[[str, dict[str, Any], Ids], Reply]]] = {
    "/v1/chat/completions": ("openai.chat", openai_chat.handle),
    "/v1/responses": ("openai.responses", openai_responses.handle),
    "/v1/messages": ("anthropic.messages", anthropic_messages.handle),
}
SCENARIOS = openai_chat.SCENARIOS + openai_responses.SCENARIOS + anthropic_messages.SCENARIOS
SCENARIOS_BY_ROUTE: dict[str, tuple[str, ...]] = {
    "/v1/chat/completions": openai_chat.SCENARIOS,
    "/v1/responses": openai_responses.SCENARIOS,
    "/v1/messages": anthropic_messages.SCENARIOS,
}


class TruthLog:
    """Every request the fake got and what it sent back. Thread-safe."""

    def __init__(self) -> None:
        self._entries: list[dict[str, Any]] = []
        self._lock = threading.Lock()

    def add(self, entry: dict[str, Any]) -> None:
        with self._lock:
            entry["seq"] = len(self._entries) + 1
            self._entries.append(entry)

    def entries(self) -> list[dict[str, Any]]:
        with self._lock:
            return json.loads(json.dumps(self._entries))

    def clear(self) -> None:
        with self._lock:
            self._entries.clear()

    def summary(self) -> dict[str, Any]:
        entries = self.entries()
        return {
            "calls": len(entries),
            "tokens_per_call": [e["usage"] for e in entries],
            "response_ids": [e["response_id"] for e in entries],
        }


class _Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server: _Server

    def log_message(self, *args: Any) -> None:
        pass

    def do_POST(self) -> None:
        raw = self.rfile.read(int(self.headers.get("Content-Length") or 0))
        path = self.path.split("?", 1)[0]
        try:
            req = json.loads(raw or b"{}")
        except ValueError:
            req = {}
        api, handler = ROUTES.get(path, ("unknown", None))
        # An override picks the scenario for a route regardless of the model name (used by audit).
        scenario = self.server.overrides.get(path) or str(req.get("model", ""))
        if handler is None:
            reply = json_reply(404, {"error": {"message": f"no route {path}", "type": "not_found"}}, outcome="http_error")
        else:
            reply = handler(scenario, req, self.server.ids)
        self.server.log.add({
            "api": api,
            "path": path,
            "scenario": scenario,
            "stream": bool(req.get("stream")),
            "include_usage": bool((req.get("stream_options") or {}).get("include_usage")),
            "n": req.get("n"),
            **reply.facts(),
        })
        self._send(reply)

    def _send(self, reply: Reply) -> None:
        self.send_response(reply.status)
        self.send_header("Content-Type", reply.content_type)
        for k, v in reply.headers.items():
            self.send_header(k, v)
        if reply.cut:
            # Promise more bytes than we send, then drop the connection.
            self.send_header("Content-Length", str(len(reply.body) + 512))
            self.end_headers()
            self.wfile.write(reply.body)
            self.wfile.flush()
            try:
                self.connection.shutdown(socket.SHUT_RDWR)
            except OSError:
                pass
            self.close_connection = True
            return
        self.send_header("Content-Length", str(len(reply.body)))
        self.end_headers()
        self.wfile.write(reply.body)


class _Server(ThreadingHTTPServer):
    daemon_threads = True
    log: TruthLog
    ids: Ids
    overrides: dict[str, str]


class FakeProvider:
    """Use as a context manager, or call start() and stop().

    overrides maps a route (e.g. "/v1/chat/completions") to the fake scenario
    every request on that route gets, whatever model the app asks for.
    """

    def __init__(self, overrides: dict[str, str] | None = None) -> None:
        self.overrides = dict(overrides or {})
        self.log = TruthLog()
        self._server: _Server | None = None
        self._thread: threading.Thread | None = None

    def start(self) -> FakeProvider:
        server = _Server(("127.0.0.1", 0), _Handler)
        server.log = self.log
        server.ids = Ids()
        server.overrides = self.overrides
        self._server = server
        self._thread = threading.Thread(target=server.serve_forever, kwargs={"poll_interval": 0.05}, name="trueup-fake", daemon=True)
        self._thread.start()
        return self

    def stop(self) -> None:
        if self._server is not None:
            self._server.shutdown()
            self._server.server_close()
            self._server = None

    def __enter__(self) -> FakeProvider:
        return self.start()

    def __exit__(self, *exc: Any) -> None:
        self.stop()

    @property
    def port(self) -> int:
        assert self._server is not None, "fake not started"
        return self._server.server_address[1]

    @property
    def base_url(self) -> str:
        """Anthropic base_url (the SDK adds /v1)."""
        return f"http://127.0.0.1:{self.port}"

    @property
    def openai_base_url(self) -> str:
        return f"{self.base_url}/v1"

